import{_ as r,c as a,o as t,a2 as i}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"Erik Purdue","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/Erik-Purdue.md","filePath":"entries/people/Erik-Purdue.md"}'),o={name:"entries/people/Erik-Purdue.md"};function n(s,e,l,u,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="erik-purdue" tabindex="-1">Erik Purdue <a class="header-anchor" href="#erik-purdue" aria-label="Permalink to &quot;Erik Purdue&quot;">​</a></h1><hr><p><strong>OCCUPATION</strong>: Director of Operations<br><strong>ORGANIZATION</strong>: St. Juniper Research Campus, Miter Corporation<br><strong>ACTIVE</strong>: Early 2000s (documented)<br><strong>STATUS</strong>: Unknown</p><hr><p>Erik Purdue was the Director of Operations at the <a href="./../locations/Saint-Juniper-Research-Campus">St. Juniper Research Campus</a> under <a href="./../organizations/Miter-Corporation">Miter Corporation</a> oversight. He served during the period when subject <a href="./../subjects/G-BOY">G*BOY (G-304)</a> escaped from containment and was subsequently formally admonished by <a href="./Agent-K">Agent K</a>.</p><p><strong>At a glance</strong></p><ul><li>Director of Operations at St. Juniper Research Campus, Miter Corporation</li><li>Oversaw facility operations during the G-304 containment period</li><li>Formally admonished by Agent K following G-304&#39;s escape</li><li>Tenure concluded shortly after the containment breach incident</li><li>Specific operational decisions leading to breach remain undisclosed</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Erik Purdue served as Director of Operations at Miter Corporation&#39;s St. Juniper Research Campus, where he held administrative authority over the facility&#39;s experimental programs and security protocols. His tenure as director included oversight during the period when subject G-304 was housed at the facility and subsequently escaped from containment.</p><h2 id="career-at-miter-corporation" tabindex="-1">Career at Miter Corporation <a class="header-anchor" href="#career-at-miter-corporation" aria-label="Permalink to &quot;Career at Miter Corporation&quot;">​</a></h2><h3 id="operational-authority" tabindex="-1">Operational Authority <a class="header-anchor" href="#operational-authority" aria-label="Permalink to &quot;Operational Authority&quot;">​</a></h3><p>As Director of Operations, Purdue held responsibility for:</p><ul><li>Day-to-day management of St. Juniper Research Campus facilities</li><li>Security protocols for high-value experimental subjects</li><li>Coordination between research divisions and Miter Corporation oversight</li><li>Implementation of directives from higher-level Miter operatives</li></ul><h3 id="g-304-containment" tabindex="-1">G-304 Containment <a class="header-anchor" href="#g-304-containment" aria-label="Permalink to &quot;G-304 Containment&quot;">​</a></h3><p>Purdue oversaw operations during the period when G-304 (also designated &quot;G*BOY&quot;) was contained at the facility. The subject was housed under high-security protocols due to its designation as a Tier-0 experimental subject.</p><p>During Purdue&#39;s tenure, G-304 escaped from the facility, resulting in a major security breach. The circumstances of the escape and the specific security protocols in place at the time have not been made public.</p><h2 id="formal-admonishment" tabindex="-1">Formal Admonishment <a class="header-anchor" href="#formal-admonishment" aria-label="Permalink to &quot;Formal Admonishment&quot;">​</a></h2><p>Following G-304&#39;s escape, Agent K delivered a formal admonishment to Purdue regarding his handling of facility operations and security protocols during the containment period. The admonishment held Purdue responsible for operational failures that enabled the breach.</p><p>The specific nature of the failures cited in the admonishment and the extent of Purdue&#39;s culpability remain matters of internal Miter Corporation review.</p><h2 id="career-conclusion" tabindex="-1">Career Conclusion <a class="header-anchor" href="#career-conclusion" aria-label="Permalink to &quot;Career Conclusion&quot;">​</a></h2><p>Purdue&#39;s tenure as Director of Operations concluded following the G-304 containment breach. His current whereabouts and subsequent career activities are unknown.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Agent-K">Agent K</a></li><li><a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">St. Juniper Research Campus</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><strong>E01_PT1_TheFormation_transcript</strong> — Narrative sequence of ANGEL/Agent K admonishing Erik Purdue</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',27)])])}const m=r(o,[["render",n]]);export{p as __pageData,m as default};
